use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let intervals: Vec<(i64, i64)> = input.as_array().unwrap().iter().map(|v| (v[0].as_i64().unwrap(), v[1].as_i64().unwrap())).collect();
    let mut intervals = intervals.sort_unstable_by_key(|&(start, _)| start).collect();
    let mut result = vec![(intervals[0].0, intervals[0].1)];
    for i in 1..intervals.len() {
        if intervals[i].0 <= result.last().unwrap().1 {
            result.last().1 = intervals[i].1.max(result.last().unwrap().1);
        } else {
            result.push(intervals[i]);
        }
    }
    Value::Array(result.into_iter().map(|v| Value::Number(v.0 as f64)).collect())
}
